INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('PRANIC_HEALING','12056313','Pranic healing: an energy-based healing practice for the contemporary nurse.','https://pubmed.ncbi.nlm.nih.gov/12056313/','CONTEXT_ONLY','Narrative review introducing Pranic Healing to nursing. Arguments and selected discoveries are not original controlled clinical results.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('PRANIC_HEALING','12889412','Introducing the Pranic Healing system to holistic nursing practice.','https://pubmed.ncbi.nlm.nih.gov/12889412/','CONTEXT_ONLY','Indexed review on introducing Pranic Healing to nursing; no PubMed abstract available. No efficacy outcomes can be extracted; use for teaching/citation context pending original text.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('PRANIC_HEALING','15040779','Complementary and alternative medicine: the move into mainstream health care.','https://pubmed.ncbi.nlm.nih.gov/15040779/','CONTEXT_ONLY','Broad CAM policy/practice discussion mentioning Pranic Healing. Population-use statistics are not PH efficacy results.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('POLARITY_THERAPY','15127775','Polarity addresses the "whole" in holistic.','https://pubmed.ncbi.nlm.nih.gov/15127775/','CONTEXT_ONLY','Narrative Polarity process review. Describes energetic rationale and possible uses, not a completed controlled efficacy experiment.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('REIKI','15992229','Positive well-being changes associated with giving and receiving Johrei healing.','https://pubmed.ncbi.nlm.nih.gov/15992229/','ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING','236 participants rated feelings/well-being before/after giving or receiving Johrei. Receivers had greater negative-emotion reductions; both roles improved positive states. No untreated/sham comparator, so role contrast does not establish energy-specific efficacy.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('THERAPEUTIC_TOUCH','15992229','Positive well-being changes associated with giving and receiving Johrei healing.','https://pubmed.ncbi.nlm.nih.gov/15992229/','ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING','236 participants rated feelings/well-being before/after giving or receiving Johrei. Receivers had greater negative-emotion reductions; both roles improved positive states. No untreated/sham comparator, so role contrast does not establish energy-specific efficacy.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('JOHREI','15992229','Positive well-being changes associated with giving and receiving Johrei healing.','https://pubmed.ncbi.nlm.nih.gov/15992229/','ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING','236 participants rated feelings/well-being before/after giving or receiving Johrei. Receivers had greater negative-emotion reductions; both roles improved positive states. No untreated/sham comparator, so role contrast does not establish energy-specific efficacy.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('PRANIC_HEALING','19175256','Pranic healing.','https://pubmed.ncbi.nlm.nih.gov/19175256/','CONTEXT_ONLY','Pranic Healing narrative review asserting molecular/energy effects. No original controlled sample or quantitative endpoint provided in abstract; assertion not validation.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('JOHREI','20832764','Johrei, a Japanese healing technique, enhances the growth of sucrose crystals.','https://pubmed.ncbi.nlm.nih.gov/20832764/','ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING','Sucrose-crystallization experiments compare Johrei-treated and untreated solutions, reporting faster growth. Nonbiological outcome does not establish patient efficacy or mechanism; sample, environmental controls and precision need full text.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('AGNIHOTRA','21897457','Agnihotra in the treatment of alcoholism.','https://pubmed.ncbi.nlm.nih.gov/21897457/','ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING','18 alcoholism cases with repeated Agnihotra; abstinence reported after two weeks and 55% beyond eight weeks. Uncontrolled series, selection/other-treatment confounding and ascertainment limit causal efficacy; not a demonstrated cure.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('AGNIHOTRA','21927247','Agnihotra - a useful adjunct in recovery of a resistant demotivated smack addict.','https://pubmed.ncbi.nlm.nih.gov/21927247/','ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING','One poorly motivated opioid-addiction case after withdrawal, four weeks of Agnihotra and reported one-year follow-up. Uncontrolled recovery cannot establish treatment efficacy or relapse prevention.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('BIOGEOMETRY','22714237','Normal and diseased personal eye modeling using age-appropriate lens parameters.','https://pubmed.ncbi.nlm.nih.gov/22714237/','EXCLUDED_NAME_COLLISION','Ocular optical modeling using lens bio-geometry. Not BioGeometry energy-healing method.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('JOHREI','22924412','Comment on Some implications of the reported effects of Johrei on the viability and proliferation of cultured cancer cells in vitro.','https://pubmed.ncbi.nlm.nih.gov/22924412/','CONTEXT_ONLY','Comment on Johrei cultured-cancer-cell findings, with no abstract. Commentary is not an independent experiment; obtain text for methodological criticism/citation context.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
