INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('SPIRITUALIST_HEALING','24310951','Transmigration, liminality, and spiritualist healing.','https://pubmed.ncbi.nlm.nih.gov/24310951/','CONTEXT_ONLY','Ethnographic Spiritualist church observations in New York; describes rituals and symbolic states. Named tradition present but no controlled clinical endpoint or measured therapeutic efficacy.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
