INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('JOHREI','26520228','Johrei Effects on Water: A Pilot Study by Counting Drops.','https://pubmed.ncbi.nlm.nih.gov/26520228/','ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING','Four Johrei practitioners, modeled water-drop behavior versus untreated samples. Selected parameters changed for two practitioners; no patient efficacy tested. Model fit is not replication or proof of a healing mechanism.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
