INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('CHAKRA_AURA','28483188','Agnihotra Yajna: A Prototype of South Asian Traditional Medical Knowledge.','https://pubmed.ncbi.nlm.nih.gov/28483188/','ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING','Agnihotra smoke volatile compounds assessed by GC-MS after modified offerings. Chemical characterization, not controlled clinical treatment or measured chakra/entropy validation; smoke composition alone does not establish safe therapeutic exposure.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
