INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('BIOGEOMETRY','28713718','Ergonomics and Biogeometry of Perforator/Propeller Flaps in the Lower Limb Reconstruction.','https://pubmed.ncbi.nlm.nih.gov/28713718/','EXCLUDED_NAME_COLLISION','Perforator/propeller flap surgical biogeometry; no named BioGeometry healing intervention. Title establishes surgical topic, abstract unavailable.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('BENGSTON_METHOD','29083972','Inhaled Corticosteroid-Containing Treatment Escalation and Outcomes for Patients with Asthma in a U.S. Health Care Organization.','https://pubmed.ncbi.nlm.nih.gov/29083972/','EXCLUDED_NAME_COLLISION','Inhaled-corticosteroid escalation claims study; Bengston is an author surname, not a healing method.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('PRANIC_HEALING','31341443','The Effects of Meditation on Twin Hearts on P300 Values: A Repeated Measures Comparison of Nonmeditators and the Experienced.','https://pubmed.ncbi.nlm.nih.gov/31341443/','ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING','12 experienced Twin Hearts meditators versus 12 nonmeditators, repeated pre/post auditory P300 measures. Selected EEG changes reported; cross-sectional experience and no matched sham limit causation. Surrogate processing measures do not validate PH recipient treatment.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('PRANIC_HEALING','31668156','Meditation-induced psychosis: a narrative review and individual patient data analysis.','https://pubmed.ncbi.nlm.nih.gov/31668156/','CONTEXT_ONLY','Narrative review of 28 reported psychosis cases across varied meditations including PH. Case associations and precipitating factors do not prove causation or estimate incidence; retain adverse-event context without assigning all cases to PH.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('BENGSTON_METHOD','35784417','Age estimation of individuals aged 5-23 years based on dental development of the Indonesian population.','https://pubmed.ncbi.nlm.nih.gov/35784417/','EXCLUDED_NAME_COLLISION','Dental development atlas using a modified Bengston eruption system; no Bengston healing intervention.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('BIOGEOMETRY','36514421','Patient Reported Outcomes of Scalp and Forehead Reconstruction for Defects Following Oncological Resections (North-East Indian Tertiary Cancer Centre Study).','https://pubmed.ncbi.nlm.nih.gov/36514421/','EXCLUDED_NAME_COLLISION','Scalp/forehead oncological surgical reconstruction outcomes using tissue bio-geometry. Not BioGeometry energy treatment.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('PRANIC_HEALING','37119543','Understanding Pranic Energy Experiences: A Qualitative Approach.','https://pubmed.ncbi.nlm.nih.gov/37119543/','ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING','100 participants'' hand-sensitization reports from 2014, retrospective qualitative analysis explicitly using Master Choa Kok Sui practice. Sensation themes do not objectively demonstrate prana detection or controlled treatment benefit.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('BENGSTON_METHOD','37325440','Differential In Vivo Effects on Cancer Models by Recorded Magnetic Signals Derived From a Healing Technique.','https://pubmed.ncbi.nlm.nih.gov/37325440/','ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING','Recorded Bengston signals four hours daily approximately one month in three mouse cancer models. Breast-tumor effect reported, melanoma largely null, bladder tumors failed to develop. Sample/room confounding/full bias review pending; no human anticancer efficacy established.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('PRANIC_HEALING','37711602','Perception of Subtle Energy "Prana", and Its Effects During Biofield Practices: A Qualitative Meta-Synthesis.','https://pubmed.ncbi.nlm.nih.gov/37711602/','CONTEXT_ONLY','Qualitative meta-synthesis of 19 heterogeneous prana/biofield perception studies. Describes felt experiences; no objective energy validation or independent clinical replication.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('REIKI','37711602','Perception of Subtle Energy "Prana", and Its Effects During Biofield Practices: A Qualitative Meta-Synthesis.','https://pubmed.ncbi.nlm.nih.gov/37711602/','CONTEXT_ONLY','Qualitative meta-synthesis of 19 heterogeneous prana/biofield perception studies. Describes felt experiences; no objective energy validation or independent clinical replication.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('SPIRITUALIST_HEALING','3781717','The social consequence of wellness: a view of healing outcomes from micro and macro perspectives.','https://pubmed.ncbi.nlm.nih.gov/3781717/','CONTEXT_ONLY','Mexican Spiritualist ethnography analyzes individual/social outcomes. No controlled efficacy comparison; distinguish cultural system from other Spiritualist lineages.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('BIOGEOMETRY','39678747','Utility of Keystone Flap in Armory of Dermatosurgeons.','https://pubmed.ncbi.nlm.nih.gov/39678747/','EXCLUDED_NAME_COLLISION','Keystone surgical flap reconstruction with anatomical bio-geometry; no named BioGeometry energy treatment.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('BENGSTON_METHOD','4879041','Ralph G. Bengston.','https://pubmed.ncbi.nlm.nih.gov/4879041/','EXCLUDED_NAME_COLLISION','Historical biography of Ralph G. Bengston, no abstract or Bengston Healing Method experiment.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_screen (practice_code,pmid,title,source_url,screening_status,screening_reason) VALUES ('SPIRITUALIST_HEALING','7408525','Non-medical treatments and their outcomes.','https://pubmed.ncbi.nlm.nih.gov/7408525/','ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING','Follow-up observations at a Mexican Spiritualist temple report more failures than successes and describe symbolic/tactile practices. No comparator or effect counts in abstract; cultural specificity limits transfer to other Spiritualist lineages.') ON DUPLICATE KEY UPDATE title=VALUES(title),screening_status=VALUES(screening_status),screening_reason=VALUES(screening_reason);
INSERT INTO ilb_ehr_candidate_extraction (practice_code,pmid,material_reviewed,interpretation_text,remaining_work,reviewed_on,reviewer_text) VALUES ('PRANIC_HEALING','39667977','ABSTRACT','46 children randomized to Rogers-based Pranic Healing or usual care during venipuncture, five minutes before/during/after; selected pain/vital signs favored intervention. Abstract identifies Rogers Therapeutic Touch theory, not Master Choa Kok Sui lineage. Keep distinct until Methods/training confirm identity; masking description needs verification.','Resolve full-text access and exact lineage where needed; independently assess bias, prespecified outcomes, notices and overlapping cohorts. Context and exclusions are not efficacy appraisals.','2026-09-30','ILMB single-reviewer primary-source extraction') ON DUPLICATE KEY UPDATE material_reviewed=VALUES(material_reviewed),interpretation_text=VALUES(interpretation_text),remaining_work=VALUES(remaining_work),reviewed_on=VALUES(reviewed_on),reviewer_text=VALUES(reviewer_text);
INSERT INTO ilb_ehr_screen_assessment (practice_code,pmid,screening_level,assessed_on,reviewer_text) VALUES ('PRANIC_HEALING','39667977','ABSTRACT','2026-09-30','ILMB single-reviewer primary-source extraction') ON DUPLICATE KEY UPDATE screening_level=VALUES(screening_level),assessed_on=VALUES(assessed_on),reviewer_text=VALUES(reviewer_text);
