INSERT INTO ilb_ehr_candidate_extraction (practice_code,pmid,material_reviewed,interpretation_text,remaining_work,reviewed_on,reviewer_text) VALUES ('THERAPEUTIC_TOUCH','41709616','FULL_TEXT','46 students, 23/23, randomizer-generated allocation; no sham or participant masking. Baseline anxiety 58.91 versus 40.26; post 25.60 versus 47.43. ANCOVA eta squared .771, but baseline imbalance/expectations and unblinded self-report create substantial bias concern. Procedure: seated, head-to-foot rhythmic scanning approximately 5 cm away, reassess/rebalance, twenty minutes, then rest; no grades measured. Authors report no conflicts or financial support.','Independent bias assessment, registry-history/prespecified endpoint verification, publisher notices and primary-data reconciliation remain open.','2026-09-30','ILMB single-reviewer primary-source extraction') ON DUPLICATE KEY UPDATE material_reviewed=VALUES(material_reviewed),interpretation_text=VALUES(interpretation_text),remaining_work=VALUES(remaining_work),reviewed_on=VALUES(reviewed_on),reviewer_text=VALUES(reviewer_text);
INSERT INTO ilb_ehr_screen_assessment (practice_code,pmid,screening_level,assessed_on,reviewer_text) VALUES ('THERAPEUTIC_TOUCH','41709616','FULL_TEXT','2026-09-30','ILMB single-reviewer primary-source extraction') ON DUPLICATE KEY UPDATE screening_level=VALUES(screening_level),assessed_on=VALUES(assessed_on),reviewer_text=VALUES(reviewer_text);
INSERT INTO ilb_ehr_candidate_extraction (practice_code,pmid,material_reviewed,interpretation_text,remaining_work,reviewed_on,reviewer_text) VALUES ('THERAPEUTIC_TOUCH','27482166','FULL_TEXT','90 male cancer patients, 30/30/30 TT/placebo/usual care, convenience recruitment. Allocation method/concealment and assessor masking not described. Seven ten-to-fifteen-minute sessions every three days: deep breathing, scan 5-10 cm away, head-to-foot cleansing and individualized transfer; sham unordered gestures. Selected pain-interference comparisons favored TT. Many endpoints, no extracted confidence intervals and absent rigorous adverse-event ascertainment preclude broad safety claims; IRCT201412094115N3 not independently matched. Authors declare no conflict.','Independent bias assessment, registry-history/prespecified endpoint verification, publisher notices and primary-data reconciliation remain open.','2026-09-30','ILMB single-reviewer primary-source extraction') ON DUPLICATE KEY UPDATE material_reviewed=VALUES(material_reviewed),interpretation_text=VALUES(interpretation_text),remaining_work=VALUES(remaining_work),reviewed_on=VALUES(reviewed_on),reviewer_text=VALUES(reviewer_text);
INSERT INTO ilb_ehr_screen_assessment (practice_code,pmid,screening_level,assessed_on,reviewer_text) VALUES ('THERAPEUTIC_TOUCH','27482166','FULL_TEXT','2026-09-30','ILMB single-reviewer primary-source extraction') ON DUPLICATE KEY UPDATE screening_level=VALUES(screening_level),assessed_on=VALUES(assessed_on),reviewer_text=VALUES(reviewer_text);
INSERT INTO ilb_ehr_candidate_extraction (practice_code,pmid,material_reviewed,interpretation_text,remaining_work,reviewed_on,reviewer_text) VALUES ('JOHREI','17549235','FULL_TEXT','Four control/four Johrei experiments, 800/856 observed glial cells, four X-ray doses. Randomized wells and scientists blinded. Thirty-minute raised-hand intention at least 20 cm away after four-hour baseline; observation 22.5 hours. Division p=.560 and death p=.456 null; dose significant. Experiment, not individual cell, is replication unit. Funding Center for Science of Life/NCCAM; no patient radiation-protection efficacy established.','Independent bias assessment, registry-history/prespecified endpoint verification, publisher notices and primary-data reconciliation remain open.','2026-09-30','ILMB single-reviewer primary-source extraction') ON DUPLICATE KEY UPDATE material_reviewed=VALUES(material_reviewed),interpretation_text=VALUES(interpretation_text),remaining_work=VALUES(remaining_work),reviewed_on=VALUES(reviewed_on),reviewer_text=VALUES(reviewer_text);
INSERT INTO ilb_ehr_screen_assessment (practice_code,pmid,screening_level,assessed_on,reviewer_text) VALUES ('JOHREI','17549235','FULL_TEXT','2026-09-30','ILMB single-reviewer primary-source extraction') ON DUPLICATE KEY UPDATE screening_level=VALUES(screening_level),assessed_on=VALUES(assessed_on),reviewer_text=VALUES(reviewer_text);
INSERT INTO ilb_ehr_candidate_extraction (practice_code,pmid,material_reviewed,interpretation_text,remaining_work,reviewed_on,reviewer_text) VALUES ('EXTERNAL_QIGONG','15102336','FULL_TEXT','Three astrocyte colony-formation studies: four pilot, fourteen formal and thirty replication Qigong/sham comparisons, each with equal numbers of systematic negative-control comparisons. Cell plates/locations randomized, coded counting/analysis blinded. Formal sham always first; replication order randomized with temperature logging. Twenty-minute treatment at least 10 cm away; no reproducible effect, pooled result nonsignificant. Environmental variability and absent present-but-not-treating practitioner control limit mechanism inference. NCCAM/Noetic Sciences/Fetzer support reported.','Independent bias assessment, registry-history/prespecified endpoint verification, publisher notices and primary-data reconciliation remain open.','2026-09-30','ILMB single-reviewer primary-source extraction') ON DUPLICATE KEY UPDATE material_reviewed=VALUES(material_reviewed),interpretation_text=VALUES(interpretation_text),remaining_work=VALUES(remaining_work),reviewed_on=VALUES(reviewed_on),reviewer_text=VALUES(reviewer_text);
INSERT INTO ilb_ehr_screen_assessment (practice_code,pmid,screening_level,assessed_on,reviewer_text) VALUES ('EXTERNAL_QIGONG','15102336','FULL_TEXT','2026-09-30','ILMB single-reviewer primary-source extraction') ON DUPLICATE KEY UPDATE screening_level=VALUES(screening_level),assessed_on=VALUES(assessed_on),reviewer_text=VALUES(reviewer_text);
INSERT INTO ilb_ehr_candidate_extraction (practice_code,pmid,material_reviewed,interpretation_text,remaining_work,reviewed_on,reviewer_text) VALUES ('MANTRA_PRACTICES','36121655','FULL_TEXT','80 randomized, 78 at three months, open-label TM versus wellness resources. Computer stratification by age/sex through protected REDCap module. Five instructional days then twenty minutes twice daily and three follow-ups. Primary GSI difference -1.8, CI -4.2 to .6, p=.13 nonsignificant; selected secondary burnout/anxiety positive, no multiplicity adjustment. One-month surveys missing for 12/20 participants due to app error. No reported adverse events; expectancy and secondary-outcome testing constrain interpretation.','Independent bias assessment, registry-history/prespecified endpoint verification, publisher notices and primary-data reconciliation remain open.','2026-09-30','ILMB single-reviewer primary-source extraction') ON DUPLICATE KEY UPDATE material_reviewed=VALUES(material_reviewed),interpretation_text=VALUES(interpretation_text),remaining_work=VALUES(remaining_work),reviewed_on=VALUES(reviewed_on),reviewer_text=VALUES(reviewer_text);
INSERT INTO ilb_ehr_screen_assessment (practice_code,pmid,screening_level,assessed_on,reviewer_text) VALUES ('MANTRA_PRACTICES','36121655','FULL_TEXT','2026-09-30','ILMB single-reviewer primary-source extraction') ON DUPLICATE KEY UPDATE screening_level=VALUES(screening_level),assessed_on=VALUES(assessed_on),reviewer_text=VALUES(reviewer_text);
