-- Source-specific identity, full-text and registry follow-up. No scientific completion promoted.
ALTER TABLE ilb_ehr_candidate_extraction MODIFY material_reviewed ENUM('ABSTRACT','NO_ABSTRACT','FULL_TEXT') NOT NULL;
CREATE TABLE IF NOT EXISTS ilb_ehr_source_access (
 pmid VARCHAR(20) PRIMARY KEY, pmc_id VARCHAR(24) NOT NULL, source_url TEXT NOT NULL,
 access_status ENUM('BODY_RETRIEVED','NO_BODY_RETURNED') NOT NULL,
 review_status ENUM('TARGETED_FULL_TEXT_REVIEWED','REVIEW_PENDING','ACCESS_GAP') NOT NULL,
 checked_on DATE NOT NULL, access_note TEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ilb_ehr_registry_review (
 registry_id VARCHAR(24) PRIMARY KEY, practice_code VARCHAR(64) NOT NULL,
 paper_pmids VARCHAR(128) NOT NULL, source_url TEXT NOT NULL,
 correspondence_status ENUM('PARTIAL','DISCREPANCY') NOT NULL,
 findings_text TEXT NOT NULL, reviewed_on DATE NOT NULL,
 FOREIGN KEY(practice_code) REFERENCES ilb_ehr_practice(practice_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ilb_ehr_expanded_triage (
 pmid VARCHAR(20) PRIMARY KEY, title TEXT NOT NULL, source_url TEXT NOT NULL,
 triage_hint VARCHAR(48) NOT NULL, hint_reason TEXT NOT NULL,
 review_status ENUM('PRIMARY_RECORD_REVIEWED','SCREENING_PENDING') NOT NULL,
 triage_provenance VARCHAR(128) NOT NULL, checked_on DATE NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ilb_ehr_expanded_mapping (
 practice_code VARCHAR(64) NOT NULL, pmid VARCHAR(20) NOT NULL,
 PRIMARY KEY(practice_code,pmid), FOREIGN KEY(practice_code) REFERENCES ilb_ehr_practice(practice_code),
 FOREIGN KEY(pmid) REFERENCES ilb_ehr_expanded_triage(pmid)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
START TRANSACTION;
UPDATE ilb_ehr_candidate_screen SET screening_status='IDENTITY_UNCONFIRMED',screening_reason='46 children randomized to Rogers-based Pranic Healing or usual care during venipuncture, five minutes before/during/after; selected pain/vital signs favored intervention. Abstract identifies Rogers Therapeutic Touch theory, not Master Choa Kok Sui lineage. Keep distinct until Methods/training confirm identity; masking description needs verification.' WHERE practice_code='PRANIC_HEALING' AND pmid='39667977';
UPDATE ilb_ehr_candidate_screen SET screening_status='CONTEXT_ONLY',screening_reason='Quality review of 45 clinical/45 laboratory healing studies through 2001. Includes heterogeneous hands-on/distant modalities and major methodological problems. Use for citation chasing, not primary replication or Spiritualist-specific efficacy.' WHERE practice_code='DISTANCE_HEALING' AND pmid='12776468';
UPDATE ilb_ehr_candidate_screen SET screening_status='ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING',screening_reason='Named Reconnective Healers confirmed in abstract: 50 practitioners versus 31 Reiki masters and 32 controls during self-practice. HRV decreased in Reconnective group, contrary to greater relaxation; blood perfusion increased. No recipient treatment efficacy or random assignment demonstrated.' WHERE practice_code='RECONNECTIVE_HEALING' AND pmid='22863644';
UPDATE ilb_ehr_candidate_screen SET screening_status='CONTEXT_ONLY',screening_reason='Sixteen coaching students, phase-one training-curriculum evaluation. Abstract does not identify Eden specifically or give a controlled clinical outcome. Retain as educational context, without attribution to Eden efficacy.' WHERE practice_code='EDEN_ENERGY_MEDICINE' AND pmid='35435869';
UPDATE ilb_ehr_candidate_screen SET screening_status='ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING',screening_reason='Polarity Therapy explicitly identified: 10 treatment, 10 sham and 10 standing-observer volunteers, gamma detector readings at four sites. Reported lower counts do not establish emitted healing energy, beneficial radiation hormesis or cancer survival. Instrument/environment controls and allocation need full-text appraisal.' WHERE practice_code='POLARITY_THERAPY' AND pmid='10394674';
UPDATE ilb_ehr_candidate_screen SET screening_status='ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING',screening_reason='JSJ explicitly one of multiple CAM activities in a 49-year-old breast-cancer survivor observed for 28 days. Urinary IL6/fatigue time-series associations cannot isolate JSJ or causation. Same patient/period as PMID33412954 is probable; treat as overlapping until reconciled.' WHERE practice_code='JIN_SHIN_JYUTSU' AND pmid='34149467';
UPDATE ilb_ehr_candidate_screen SET screening_status='ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING',screening_reason='JSJ explicitly among workplace wellness modalities over 11 months; independent anonymous samples 166 baseline/158 follow-up. Self-care/healing-culture scores did not significantly change. Quality-improvement evaluation cannot isolate JSJ or treat the samples as paired longitudinal individuals.' WHERE practice_code='JIN_SHIN_JYUTSU' AND pmid='42709485';
UPDATE ilb_ehr_candidate_screen SET screening_status='ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING',screening_reason='JSJ explicitly included with music, physiotherapy and energy healing in one breast-cancer survivor''s 28-day time series. Cyclic mood/neopterin associations; no comparator or isolated JSJ effect. Probable overlap with PMID34149467, not independent replication.' WHERE practice_code='JIN_SHIN_JYUTSU' AND pmid='33412954';
UPDATE ilb_ehr_candidate_screen SET screening_status='ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING',screening_reason='Mantra explicitly identified: 57 randomized across baseline lengths/four eight-week packages, 42 analyzed. Ethical-education combinations had larger well-being gains; mantra-only well-being unchanged and stress direction unfavorable. Related cohort reports PMIDs36142006/35956171 must not be counted independently.' WHERE practice_code='MANTRA_PRACTICES' AND pmid='34421729';
UPDATE ilb_ehr_candidate_screen SET screening_status='ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING',screening_reason='42 completers from 57 randomized across the same four mantra/yoga/ethics packages as PMID34421729. Selected embodied-awareness measures improved; mantra-only affect least favorable. Follow-up two/twelve months; secondary report, not independent replication or energy-mechanism proof.' WHERE practice_code='MANTRA_PRACTICES' AND pmid='36142006';
UPDATE ilb_ehr_candidate_screen SET screening_status='ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING',screening_reason='24 people with spinal-cord-injury pain randomized to combined mindfulness/mantra/imagery or health education, weekly two-hour classes for four weeks. Primary pain interference improved more in control, d>1; selected secondary outcomes favored combined practice. Do not attribute package to isolated mantra efficacy.' WHERE practice_code='MANTRA_PRACTICES' AND pmid='34612802';
UPDATE ilb_ehr_candidate_screen SET screening_status='ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING',screening_reason='Moderator analysis of 57 randomized participants across four eight-week mantra/yoga/ethics packages. Personality-outcome associations are exploratory; same project as PMIDs34421729/36142006. No independent replication or validated personalized treatment-selection rule established.' WHERE practice_code='MANTRA_PRACTICES' AND pmid='35956171';
UPDATE ilb_ehr_candidate_screen SET screening_status='FULL_TEXT_EXTRACTED_BIAS_PENDING',screening_reason='PMC13023138 Methods confirms practitioners trained by the Foundation for Shamanic Studies and Sandra Ingerman, supporting Core Shamanism lineage. Twenty of 23 women completed five individualized visits, including soul retrieval and integration. Randomization was to practitioners, with no untreated/sham group. Qualitative experiences are not controlled efficacy. Same cohort as PMIDs17985808/22745613; full Methods, Results and Discussion reviewed.' WHERE practice_code='CORE_SHAMANISM' AND pmid='21040886';
UPDATE ilb_ehr_candidate_screen SET screening_status='ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING',screening_reason='23 women with TMD, five visits; random assignment was to four practitioners, not treatment versus control. Pain/function improved within cohort. Lineage and cohort connection are confirmed by Methods and citation in full companion report PMID21040886 (Foundation for Shamanic Studies/Sandra Ingerman). Do not count as an RCT efficacy comparison.' WHERE practice_code='CORE_SHAMANISM' AND pmid='17985808';
UPDATE ilb_ehr_candidate_screen SET screening_status='CONTEXT_ONLY',screening_reason='Scoping review of heterogeneous shamanism: 16 publications, one clinical trial, case series/reports. Use for citation chasing; review counts are not independent trials and do not establish Core Shamanism lineage for every included study.' WHERE practice_code='CORE_SHAMANISM' AND pmid='41281382';
UPDATE ilb_ehr_candidate_screen SET screening_status='IDENTITY_UNCONFIRMED',screening_reason='Six veterans in uncontrolled shamanic-healing PTSD case series; semi-structured ritual components and acceptability reported. Abstract does not identify Foundation for Shamanic Studies/Harner training. Core Shamanism attribution and controlled PTSD efficacy remain unconfirmed.' WHERE practice_code='CORE_SHAMANISM' AND pmid='28336055';
UPDATE ilb_ehr_candidate_screen SET screening_status='CONTEXT_ONLY',screening_reason='TMD shamanic-healing review includes three publications with matching female age range, potentially overlapping reports from one cohort. Citation chasing needed; neither three independent trials nor general Core Shamanism efficacy established.' WHERE practice_code='CORE_SHAMANISM' AND pmid='37269379';
UPDATE ilb_ehr_candidate_screen SET screening_status='ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING',screening_reason='Nine-month follow-up of the same 23-woman TMD phase-one cohort; improvements did not significantly change after treatment, p>.18. This is persistence within an uncontrolled cohort, not controlled efficacy. Companion Methods PMID21040886 confirms Foundation for Shamanic Studies lineage and shared participants.' WHERE practice_code='CORE_SHAMANISM' AND pmid='22745613';
UPDATE ilb_ehr_candidate_screen SET screening_status='IDENTITY_UNCONFIRMED',screening_reason='Fourteen therapists interviewed about power-animal guided imagery. Perceived benefits and suitability concerns described; no controlled patient outcomes or explicit Core Shamanism training lineage in abstract. Keep identity open.' WHERE practice_code='CORE_SHAMANISM' AND pmid='42030677';
UPDATE ilb_ehr_candidate_screen SET screening_status='CONTEXT_ONLY',screening_reason='Anthropological surveys and observation of more than 30 Asian shamans describe anomalous experiences and beliefs. No Core Shamanism treatment trial or objective confirmation of the belief claims.' WHERE practice_code='CORE_SHAMANISM' AND pmid='8315358';
UPDATE ilb_ehr_candidate_screen SET screening_status='CONTEXT_ONLY',screening_reason='Narrative discussion of shamanism, imagery and immune-system hypotheses. No original controlled treatment results; congruence with psychoneuroimmunology is an interpretation, not validation of Core Shamanism mechanisms.' WHERE practice_code='CORE_SHAMANISM' AND pmid='11855507';
UPDATE ilb_ehr_candidate_screen SET screening_status='EXCLUDED_WRONG_MODALITY',screening_reason='Historical Korean diary analysis of rural healthcare and Western medicines. Discussion of shamanic-healing myths does not study Core Shamanism as an intervention.' WHERE practice_code='CORE_SHAMANISM' AND pmid='30679411';
UPDATE ilb_ehr_candidate_screen SET screening_status='EXCLUDED_WRONG_MODALITY',screening_reason='Psychotherapy commentary drawn from 700 Latino immigrant families and Peruvian shamanic roots. This is not the named Harner/Foundation for Shamanic Studies method and provides no controlled Core Shamanism efficacy result.' WHERE practice_code='CORE_SHAMANISM' AND pmid='12356595';
